params.command:
$ErrorActionPreference='Continue'
$r='C:\Users\Xxkan\mhw-mods-work-canonical'
if (!(Test-Path $r)) { Write-Error 'canonical repo missing'; exit 2 }
$env:GIT_TERMINAL_PROMPT='0'
& git -C $r fetch origin --prune '+refs/heads/*:refs/remotes/origin/*' 2>&1 | Out-Host
if ($LASTEXITCODE -ne 0) { Write-Error 'fetch failed'; exit 3 }
$deleted=@()
$kept=@()
$refs=@(& git -C $r for-each-ref --format='%(refname)' refs/remotes/origin/)
foreach($ref in $refs){
  if($ref -notmatch '^refs/remotes/origin/(.+)$'){ continue }
  $b=$Matches[1]
  if([string]::IsNullOrWhiteSpace($b) -or $b -in @('HEAD','main','heaven-bridge')){ continue }
  if($b -like 'agent/bridge-*' -or $b -like 'agent/heaven-hosted-*' -or $b -like 'integration/smart-pack-*'){
    $kept += "$b|protected-active-lane"
    continue
  }
  $sha0=(& git -C $r rev-parse "origin/$b" 2>$null).Trim()
  if($LASTEXITCODE -ne 0 -or !$sha0){ $kept += "$b|unresolved-ref"; continue }
  $safe=$false
  & git -C $r merge-base --is-ancestor "origin/$b" origin/main 2>$null
  if($LASTEXITCODE -eq 0){
    $safe=$true
    $reason='ancestor'
  } else {
    $cherry=@(& git -C $r cherry origin/main "origin/$b" 2>$null)
    if($LASTEXITCODE -eq 0 -and @($cherry | Where-Object {$_ -match '^\+ '}).Count -eq 0){
      $safe=$true
      $reason='patch-equivalent'
    }
  }
  if(!$safe){
    $plus=@($cherry | Where-Object {$_ -match '^\+ '}).Count
    $kept += "$b|unique=$plus"
    continue
  }
  $live=(& git -C $r ls-remote --heads origin "refs/heads/$b" 2>$null)
  if($LASTEXITCODE -ne 0 -or !$live){ $kept += "$b|already-absent-or-unreadable"; continue }
  $sha1=($live -split '\s+')[0]
  if($sha1 -ne $sha0){ $kept += "$b|moved-during-audit"; continue }
  & git -C $r push origin --delete -- $b 2>&1 | Out-Host
  if($LASTEXITCODE -eq 0){ $deleted += "$b|$reason" } else { $kept += "$b|delete-failed" }
}
& git -C $r fetch origin --prune 2>&1 | Out-Host
$remaining=@(& git -C $r for-each-ref --format='%(refname)' refs/remotes/origin/ | Where-Object {$_ -match '^refs/remotes/origin/(.+)$'} | ForEach-Object {$Matches[1]} | Where-Object {$_ -and $_ -notin @('HEAD','main')})
'DELETED_COUNT='+$deleted.Count
$deleted | Sort-Object
'KEPT_COUNT='+$kept.Count
$kept | Sort-Object
'REMAINING_NON_MAIN_COUNT='+$remaining.Count
'REMAINING'
$remaining | Sort-Object
